SELECT COUNT(*)
FROM broker_order_attempt
WHERE client_order_key = #{clientOrderKey}

SELECT COUNT(*)
FROM broker_order_attempt
WHERE stock_code = #{stockCode}
  AND created_at > #{after}

SELECT COUNT(*)
FROM broker_order_attempt
WHERE side = #{side}
  AND created_at >= #{from}
  AND created_at < #{to}

